-- The MIN-CUT code key (Code keys -> Parting -> MIN-CUT), from the ISCAR
-- e-catalog's MINCUT families (MIFR, MIGR, MIUR, MEFL inserts, MIFHR bars,
-- IHSR trepanning cartridges); kept if one exists.
INSERT INTO "AppSetting" ("key", "value") VALUES ('codekey.mincut', $ck${"title": "MIN-CUT code key – inserts and tools", "subtitle": "Screw-clamped inserts for internal and face grooving, undercutting and turning in small bores (MIFR, MIGR, MIUR, MEFL), MIFHR bars and IHSR trepanning cartridges", "example": "MIFR 8-1.50-0.20", "decoder": "mincut", "sections": [{"key": "i-family", "title": "Insert – family", "sample": "MIF", "rows": [{"code": "MIF", "meaning": "Internal face grooving and turning inserts (MIFR)"}, {"code": "MIG", "meaning": "Internal shallow grooving inserts (MIGR)"}, {"code": "MIU", "meaning": "45° full radius internal undercutting inserts (MIUR)"}, {"code": "MEF", "meaning": "External face grooving and turning next to shafts (MEFL)"}]}, {"key": "i-hand", "title": "Insert – hand", "sample": "R", "rows": [{"code": "R", "meaning": "Right-hand"}, {"code": "L", "meaning": "Left-hand"}]}, {"key": "i-size", "title": "Insert – size", "sample": "8", "rows": [{"code": "8", "meaning": "Size 8 (MIFHR ...-8 bars; MIGR / MIUR 8: minimum bore about 8 mm)"}, {"code": "10", "meaning": "Size 10 (MIFHR ...-10 bars)"}, {"code": "15", "meaning": "Size 15 (MIFHR ...-15 bars)"}]}, {"key": "i-width", "title": "Insert – cutting width", "sample": "1.50", "rows": [{"code": "#.##", "meaning": "Cutting width in mm (e.g. 1.50)"}, {"code": "#.#", "meaning": "Cutting width in mm (e.g. 1.5)"}]}, {"key": "i-radius", "title": "Insert – corner radius", "sample": "0.20", "rows": [{"code": "#.##", "meaning": "Corner radius in mm (0.00 = sharp; half the width = full radius)"}]}, {"key": "t-family", "title": "Tool – family", "rows": [{"code": "MIFH", "meaning": "Bars for face and internal grooving, undercutting and threading inserts (MIFHR)"}, {"code": "IHS", "meaning": "Trepanning cartridges carrying MINCUT inserts, for BHR MB32-32X63 boring heads (IHSR)"}]}, {"key": "t-hand", "title": "Tool – hand", "rows": [{"code": "R", "meaning": "Right-hand"}, {"code": "L", "meaning": "Left-hand"}]}, {"key": "t-height", "title": "Tool – shank", "rows": [{"code": "##", "meaning": "Shank diameter in mm (8, 10, 12, 16, 20)"}]}, {"key": "t-seat", "title": "Tool – insert size", "rows": [{"code": "##", "meaning": "MINCUT insert size the tool carries (8, 10, 15)"}]}, {"key": "t-dmin", "title": "Tool – grooving diameter range", "rows": [{"code": "##-##", "meaning": "Minimum – maximum axial grooving diameter in mm (e.g. 8-21)"}]}, {"key": "t-suffix", "title": "Tool – suffixes", "rows": [{"code": "C", "meaning": "With coolant (inferred)"}, {"code": "SC", "meaning": "Solid carbide shank"}, {"code": "SRK", "meaning": "SRK version (see the catalog) (inferred)"}]}]}$ck$)
ON CONFLICT ("key") DO NOTHING;
